/**
 * Shared Leaflet bootstrap for the side-panel maps (Equity, Transfer
 * reliability). Owns the three invariants every panel map needs, so the
 * panels stop re-implementing (and diverging on) them:
 *
 * 1. Deferred-mount creation via a callback ref — the container only exists
 *    once data loads, so a mount-time effect finds nothing. The ref fires on
 *    the exact commit the node appears.
 * 2. A ResizeObserver-driven invalidateSize — React layout resizes the
 *    container without window resize events (tab switches mount the panel
 *    clipped/mid-layout), and a stale internal size renders the map gray.
 * 3. Tiles keyed on [basemap, mapReady] — the mapReady counter re-runs the
 *    tile effect after the deferred mount; without it the one [basemap] run
 *    found no map and the panel stayed gray forever.
 *
 * MapView (the engine-switching network map) deliberately does NOT use this
 * hook: its lifecycle differs (own mount effect keyed on the engine flag,
 * eight layer groups built inline). If it ever collapses to this shape, it
 * should adopt the hook then.
 */
import { useCallback, useEffect, useRef, useState } from 'react';
import L from 'leaflet';
import { basemapById, defaultBasemapId } from './basemaps';

const DEFAULT_CENTER: [number, number] = [43.589, -79.6441];
const DEFAULT_ZOOM = 11;

export function useLeafletPanelMap(opts?: {
  center?: [number, number];
  zoom?: number;
}) {
  const mapRef = useRef<L.Map | null>(null);
  const layerRef = useRef<L.LayerGroup | null>(null);
  const tileLayerRef = useRef<L.TileLayer | null>(null);
  const resizeObsRef = useRef<ResizeObserver | null>(null);
  const [mapReady, setMapReady] = useState(0);
  const [basemapId, setBasemapId] = useState(defaultBasemapId);
  const basemap = basemapById(basemapId);

  // The center/zoom are read once at map creation; callers passing them
  // inline must accept first-mount-wins semantics (same as the pre-hook code).
  const optsRef = useRef(opts);
  optsRef.current = opts;

  const ref = useCallback((node: HTMLDivElement | null) => {
    if (node) {
      if (mapRef.current) return;
      const map = L.map(node, { zoomControl: true });
      mapRef.current = map;
      layerRef.current = L.layerGroup().addTo(map);
      map.setView(
        optsRef.current?.center ?? DEFAULT_CENTER,
        optsRef.current?.zoom ?? DEFAULT_ZOOM
      );
      const ro = new ResizeObserver(() => map.invalidateSize());
      ro.observe(node);
      resizeObsRef.current = ro;
      setMapReady((n) => n + 1);
    } else {
      resizeObsRef.current?.disconnect();
      resizeObsRef.current = null;
      mapRef.current?.remove();
      mapRef.current = null;
      layerRef.current = null;
      tileLayerRef.current = null;
    }
  }, []);

  // Sync basemap choice from the shared picker (broadcast via custom event).
  useEffect(() => {
    const handler = (e: Event) => {
      const id = (e as CustomEvent<string>).detail;
      if (id) setBasemapId(id);
    };
    window.addEventListener('miway:basemap', handler);
    return () => window.removeEventListener('miway:basemap', handler);
  }, []);

  // Tiles, re-attached on basemap change AND after the deferred map mount.
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    const prev = tileLayerRef.current;
    const tiles = L.tileLayer(basemap.url, { attribution: basemap.attribution });
    tiles.addTo(map);
    tileLayerRef.current = tiles;
    if (prev && map.hasLayer(prev)) map.removeLayer(prev);
    return () => {
      if (map.hasLayer(tiles)) map.removeLayer(tiles);
      if (tileLayerRef.current === tiles) tileLayerRef.current = null;
    };
  }, [basemap, mapReady]);

  return { ref, mapRef, layerRef, mapReady, basemap, basemapId };
}
